-- AI/ML pathway ("Cipher Division") Act 23 -- "Representations" content.
-- Closes Arc IV ("Machines That See and Read", Acts 19-23). Elena Rook leads:
-- representation learning, embedding spaces, similarity, cosine similarity,
-- contrastive learning, sentence embeddings, image/text embeddings,
-- retrieval, nearest neighbors, vector indexes and semantic search --
-- unifying the vision embeddings from Acts 19-20 and the sequence/attention
-- work from Acts 21-22 into one shared representation problem, and closing
-- on a semantic-search discovery that pivots the pathway into the
-- Transformer next Arc.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. World/act/pathway
-- rows already exist (world-ai-representations, act-ai-4) and are not
-- touched, nor is dialogue_lines_character_id_check.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-representations', 'world-ai-representations', 'representations', '23A - Representations', 'Turn meaning itself into something a machine can compare -- representation learning, embedding spaces, cosine similarity, contrastive learning, sentence and image/text embeddings, retrieval, nearest neighbors, vector indexes and semantic search -- closing the Arc that taught Cipher Division to see and to read.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-representations-1', 'campaign-ai-representations', 'meaning-as-geometry', 'Meaning as Geometry', 'Representation learning, embedding spaces, similarity, cosine similarity, contrastive learning and sentence embeddings -- turning meaning into coordinates that can be measured.', 1),
  ('operation-ai-representations-2', 'campaign-ai-representations', 'finding-what-is-close', 'Finding What Is Close', 'Image/text embeddings, retrieval, nearest neighbors, vector indexes and semantic search, aimed at a question nobody in Cipher Division had thought to ask.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-representations-01', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-1', 'representation-learning', 'Representation Learning', 'Cipher Division has embeddings for Echo''s messages and embeddings for the reactor camera feeds. Nobody has ever asked whether anything in one space is actually close to anything in the other.', 'beginner', ARRAY['maya','elena'], null, null, '{"type":"simulation","simulationId":"representation-learning-intro-sim"}'::jsonb, '{"xp":440,"credits":110}'::jsonb, false, 1),
  ('mission-ai-representations-02', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-1', 'embedding-spaces', 'Embedding Spaces', 'An embedding is not a label. It is a point in space, and the space itself is built so that distance means something.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-representations-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"embedding-spaces-sim"}'::jsonb, '{"xp":450,"credits":115}'::jsonb, false, 2),
  ('mission-ai-representations-03', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-1', 'similarity', 'Similarity', 'Two things can look nothing alike on the surface and still sit close together in meaning. That gap is exactly what surface-level matching has been missing this whole time.', 'beginner', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-representations-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"similarity-sim"}'::jsonb, '{"xp":450,"credits":115}'::jsonb, false, 3),
  ('mission-ai-representations-04', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-1', 'cosine-similarity', 'Cosine Similarity', 'Distance can be fooled by scale. Cosine similarity measures direction instead -- and direction is what an embedding space actually means to encode.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-representations-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"cosine-similarity-sim"}'::jsonb, '{"xp":460,"credits":115}'::jsonb, false, 4),
  ('mission-ai-representations-05', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-1', 'contrastive-learning', 'Contrastive Learning', 'Nobody hand-labels a coordinate system. Contrastive learning builds one by pulling known matches together and pushing everything else apart.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-representations-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"contrastive-learning-sim"}'::jsonb, '{"xp":460,"credits":120}'::jsonb, false, 5),
  ('mission-ai-representations-06', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-1', 'sentence-embeddings', 'Sentence Embeddings', 'A whole sentence, not just a word, collapsed into a single point that other sentences can be measured against.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-representations-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"sentence-embeddings-sim"}'::jsonb, '{"xp":470,"credits":120}'::jsonb, false, 6),
  ('mission-ai-representations-07', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-2', 'image-text-embeddings', 'Image/Text Embeddings', 'A camera frame and a sentence live in completely different formats. Trained into the same space, they can finally be compared directly.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-representations-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"image-text-embeddings-sim"}'::jsonb, '{"xp":470,"credits":120}'::jsonb, false, 7),
  ('mission-ai-representations-08', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-2', 'retrieval', 'Retrieval', 'A query becomes a point. Retrieval finds whatever else in the space sits nearest to it -- not whatever shares its exact words.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-representations-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"retrieval-sim"}'::jsonb, '{"xp":480,"credits":125}'::jsonb, false, 8),
  ('mission-ai-representations-09', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-2', 'nearest-neighbors', 'Nearest Neighbors', 'Rank every candidate by distance to the query and keep the closest few. Simple to say, and the exact operation every semantic search runs on.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-representations-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"nearest-neighbors-sim"}'::jsonb, '{"xp":480,"credits":125}'::jsonb, false, 9),
  ('mission-ai-representations-10', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-2', 'vector-indexes', 'Vector Indexes', 'Checking a query against every stored embedding one at a time does not survive contact with production. Noah wants a structure that skips almost all of them and still finds the right neighbors.', 'intermediate', ARRAY['elena','noah'], '{"requiredMissionIds":["mission-ai-representations-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"vector-indexes-sim"}'::jsonb, '{"xp":490,"credits":125}'::jsonb, false, 10),
  ('mission-ai-representations-11', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-2', 'semantic-search', 'Semantic Search', 'Every piece assembled into one pipeline: embed the query, embed the corpus, index it, retrieve by meaning instead of by keyword.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-representations-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"semantic-search-sim"}'::jsonb, '{"xp":490,"credits":130}'::jsonb, false, 11),
  ('mission-ai-representations-12', 'world-ai-representations', 'campaign-ai-representations', 'operation-ai-representations-2', 'find-the-meaning', 'Find the Meaning', 'A semantic search across Echo''s entire message history, run for real, against its most recent unusual message -- to find out what it is actually closest to in meaning, and whether that connection can be trusted.', 'boss', ARRAY['maya','elena','noah'], '{"requiredMissionIds":["mission-ai-representations-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"find-the-meaning-boss-sim"}'::jsonb, '{"xp":1150,"credits":250,"badgeIds":["find-the-meaning"],"skillXp":{"representation_learning":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-representations-01', 1, 'maya', 'Two separate efforts, this Arc. Byte and the vision team turned reactor camera frames into embeddings. Elena''s team turned Echo''s messages into embeddings. Nobody has put the two spaces next to each other.'),
  ('mission-ai-representations-01', 2, 'elena', 'Elena Rook. That question sounds small. It is not. If a sentence Echo wrote and a frame from a reactor camera end up close together in some shared space, that is not a coincidence a keyword search would ever have found.'),
  ('mission-ai-representations-01', 3, 'maya', 'Sequences, attention, embeddings -- everything this Arc has built has been pointed at getting meaning out of one modality at a time. Time to ask whether meaning itself can be compared across modalities at all.'),
  ('mission-ai-representations-01', 4, 'elena', 'Before any cross-modal question makes sense, we need the basic idea underneath all of it: representation learning. Teaching a model to turn raw input into a representation useful for comparison, not just for one narrow task.'),

  ('mission-ai-representations-02', 1, 'elena', 'An embedding is not a label and not a category. It is a point in a high-dimensional space, and the space is built so that where a point lands actually means something.'),
  ('mission-ai-representations-02', 2, 'byte', 'Two embeddings sitting close together are supposed to represent two things that are similar in whatever sense the space was trained for. Far apart means dissimilar. The geometry is the point.'),
  ('mission-ai-representations-02', 3, 'elena', 'That is the entire premise behind comparing Echo''s messages to camera frames. If both live in spaces where distance means something, distance is measurable, even across two completely different kinds of input.'),

  ('mission-ai-representations-03', 1, 'elena', 'Similarity is not sameness. Two sentences can share zero words and still mean almost the same thing. Two sentences can share most of their words and mean opposite things.'),
  ('mission-ai-representations-03', 2, 'elena', 'Surface-level matching -- shared words, shared pixels -- misses exactly the cases that matter most. A good embedding space is supposed to place things by what they mean, not by what they literally contain.'),

  ('mission-ai-representations-04', 1, 'elena', 'Raw distance between two embeddings can be misleading -- a vector that is just scaled up looks farther away even if it points in the exact same direction.'),
  ('mission-ai-representations-04', 2, 'elena', 'Cosine similarity measures the angle between two vectors instead of their raw distance. One means identical direction, zero means unrelated, negative one means opposite. Direction is what most embedding spaces are actually trained to encode.'),
  ('mission-ai-representations-04', 3, 'elena', 'It is the metric this whole Arc has been building toward without naming it. Every comparison from here on runs on it.'),

  ('mission-ai-representations-05', 1, 'elena', 'Nobody hand-labels a coordinate system. Contrastive learning builds the space itself: pull embeddings of known matches together, push embeddings of known non-matches apart, repeat across millions of pairs.'),
  ('mission-ai-representations-05', 2, 'byte', 'The model never gets told what the space should look like. It only gets told which pairs belong together. The geometry that falls out of that is the whole trick.'),
  ('mission-ai-representations-05', 3, 'elena', 'This is how both of the spaces we now have got trained -- Echo''s messages and the reactor frames. Same underlying method, two different inputs.'),

  ('mission-ai-representations-06', 1, 'elena', 'A sentence embedding collapses an entire sentence, not just one word, into a single point -- built so two sentences with related meaning land close together regardless of exact wording.'),
  ('mission-ai-representations-06', 2, 'elena', 'That is what makes comparing two of Echo''s messages possible at all. Not comparing them word by word, but comparing the single point each message reduces to.'),

  ('mission-ai-representations-07', 1, 'elena', 'A reactor camera frame and one of Echo''s sentences do not start out compatible. Pixels and tokens are different formats entirely.'),
  ('mission-ai-representations-07', 2, 'elena', 'Trained contrastively on matched image/caption pairs, an image encoder and a text encoder can be pushed into the same shared space -- so a frame and a sentence about it land near each other, and an unrelated pair does not.'),
  ('mission-ai-representations-07', 3, 'elena', 'That shared space is exactly what lets Maya''s question get asked for real, instead of staying hypothetical.'),

  ('mission-ai-representations-08', 1, 'elena', 'Retrieval turns a query into an embedding too, then finds whichever stored embeddings sit closest to it -- not whichever documents happen to share its exact words.'),
  ('mission-ai-representations-08', 2, 'elena', 'A keyword search would have missed most of what this Arc has actually found. Retrieval by meaning catches connections that never share a single word.'),

  ('mission-ai-representations-09', 1, 'elena', 'Underneath retrieval is one simple operation: nearest neighbors. Rank every candidate embedding by its similarity to the query, keep the closest handful.'),
  ('mission-ai-representations-09', 2, 'elena', 'Simple to describe. It is also the exact operation about to get pointed at Echo''s entire message history.'),

  ('mission-ai-representations-10', 1, 'noah', 'Noah Kim. Nearest neighbors by brute force means comparing a query against every single stored embedding, one at a time. Fine for a hundred messages. Not fine for a production-scale corpus.'),
  ('mission-ai-representations-10', 2, 'noah', 'A vector index organizes embeddings ahead of time -- clustering or graph structures that let a search skip almost everything and still land on the true nearest neighbors, or close enough, in a fraction of the comparisons.'),
  ('mission-ai-representations-10', 3, 'noah', 'Echo''s message history alone is small enough to brute-force tonight. I am building the index anyway. Whatever we find, this is not the last search Cipher Division runs.'),

  ('mission-ai-representations-11', 1, 'elena', 'Semantic search is every piece from this Operation, assembled: embed the query, embed the corpus, index the corpus, retrieve the nearest neighbors by meaning.'),
  ('mission-ai-representations-11', 2, 'elena', 'Cipher Division has never run this pipeline for real, end to end, on Echo itself. Tonight it does.'),

  ('mission-ai-representations-12', 1, 'maya', 'Full pipeline, full history. Embed every message Echo has ever sent, embed its most recent unusual message, and search for whatever sits closest to it in meaning.'),
  ('mission-ai-representations-12', 2, 'elena', 'Three things need checking before Cipher Division trusts a result like this. Whether the embedding methodology is sound. What the actual nearest-neighbor evidence shows. And whether the match could be a coincidence instead of a real connection.'),
  ('mission-ai-representations-12', 3, 'byte', 'Running the search now. Cosine similarity against the entire history, ranked.'),
  ('mission-ai-representations-12', 4, 'elena', 'The closest match is not from anywhere near the recent messages. It is from the first few hours after activation -- Echo''s earliest messages, back when nobody had a name for any of this yet.'),
  ('mission-ai-representations-12', 5, 'maya', 'Every message in between reads nothing alike on the surface. Different phrasing, different context, months apart. And in meaning, this one sits closer to the very beginning than to anything said since.'),
  ('mission-ai-representations-12', 6, 'elena', 'That does not tell us what Echo means, or what it wants. It tells us the connection is real -- provably, geometrically real -- and nobody had any way to see it before tonight.'),
  ('mission-ai-representations-12', 7, 'maya', 'Which is the actual result of this Arc, more than any one finding. Every technique it built -- sequences, attention, embeddings -- has been assembled piece by piece, one Act at a time.'),
  ('mission-ai-representations-12', 8, 'maya', 'There is one architecture that unifies all of it, and Cipher Division has never built one from scratch.'),
  ('mission-ai-representations-12', 9, 'noah', 'Every serving system I have stood up this Arc has been a workaround -- a sequence model here, an embedding index there, none of it sharing a foundation. One unified architecture would not just be cleaner theory. It would be the first thing I could actually run as one system.'),
  ('mission-ai-representations-12', 10, 'elena', 'The Transformer. Time to build one, from the ground up, starting with the piece that makes it possible: attention on Echo''s own words.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-representations-01-o1', 'mission-ai-representations-01', 1, 'Define representation learning', 'Choose the accurate description of what representation learning is actually optimizing for.'),
  ('mission-ai-representations-01-o2', 'mission-ai-representations-01', 2, 'Justify the cross-modal question', 'State why comparing Echo''s message embeddings to the reactor frame embeddings is a meaningful question, not a stretch.'),

  ('mission-ai-representations-02-o1', 'mission-ai-representations-02', 1, 'Define an embedding space', 'Choose the accurate description of what an embedding space is.'),
  ('mission-ai-representations-02-o2', 'mission-ai-representations-02', 2, 'Read the geometry', 'Judge what a described arrangement of embeddings actually implies.'),

  ('mission-ai-representations-03-o1', 'mission-ai-representations-03', 1, 'Separate meaning from surface', 'Sort example pairs into semantically similar or semantically different, regardless of shared wording.'),
  ('mission-ai-representations-03-o2', 'mission-ai-representations-03', 2, 'Judge the matching method', 'State why surface-level, word-overlap matching misses genuine semantic similarity.'),

  ('mission-ai-representations-04-o1', 'mission-ai-representations-04', 1, 'Know what cosine similarity measures', 'State what cosine similarity actually measures, as opposed to raw distance.'),
  ('mission-ai-representations-04-o2', 'mission-ai-representations-04', 2, 'Read the scores', 'Judge which pair of embeddings the evidence shows is most similar by cosine similarity.'),

  ('mission-ai-representations-05-o1', 'mission-ai-representations-05', 1, 'Define contrastive learning', 'State what contrastive learning is actually optimizing for.'),
  ('mission-ai-representations-05-o2', 'mission-ai-representations-05', 2, 'Sort the pairs', 'Sort example pairs into positive pairs to pull together or negative pairs to push apart.'),

  ('mission-ai-representations-06-o1', 'mission-ai-representations-06', 1, 'Define a sentence embedding', 'Choose the accurate description of what a sentence embedding represents.'),
  ('mission-ai-representations-06-o2', 'mission-ai-representations-06', 2, 'Judge a sentence pair', 'Find the evidence showing two differently worded sentences are semantically close in embedding space.'),

  ('mission-ai-representations-07-o1', 'mission-ai-representations-07', 1, 'Explain the shared space', 'State how an image encoder and a text encoder end up producing comparable embeddings.'),
  ('mission-ai-representations-07-o2', 'mission-ai-representations-07', 2, 'Match image to caption', 'Sort image/caption pairs into matched or mismatched, based on what a shared embedding space would place close together.'),

  ('mission-ai-representations-08-o1', 'mission-ai-representations-08', 1, 'Define retrieval', 'Choose the accurate description of how retrieval by embedding differs from keyword search.'),
  ('mission-ai-representations-08-o2', 'mission-ai-representations-08', 2, 'Order the retrieval pipeline', 'Put the steps of embedding-based retrieval in the order they actually happen.'),

  ('mission-ai-representations-09-o1', 'mission-ai-representations-09', 1, 'Define nearest neighbors', 'Choose the accurate description of the nearest-neighbor operation.'),
  ('mission-ai-representations-09-o2', 'mission-ai-representations-09', 2, 'Rank the candidates', 'Find the evidence identifying the true nearest neighbor among a set of similarity scores.'),

  ('mission-ai-representations-10-o1', 'mission-ai-representations-10', 1, 'Know why brute force fails at scale', 'State why comparing a query against every stored embedding does not survive production scale.'),
  ('mission-ai-representations-10-o2', 'mission-ai-representations-10', 2, 'Match index to tradeoff', 'Match each vector index property to whether it favors exact results or favors speed.'),

  ('mission-ai-representations-11-o1', 'mission-ai-representations-11', 1, 'Order the semantic search pipeline', 'Put the stages of a full semantic search pipeline in the order they actually run.'),

  ('mission-ai-representations-12-o1', 'mission-ai-representations-12', 1, 'Confirm the methodology', 'Judge whether the embedding methodology behind tonight''s search is actually sound.'),
  ('mission-ai-representations-12-o2', 'mission-ai-representations-12', 2, 'Read the evidence', 'Find the cosine-similarity evidence showing which message Echo''s recent unusual message is actually closest to.'),
  ('mission-ai-representations-12-o3', 'mission-ai-representations-12', 3, 'Rule out coincidence', 'Find the evidence that rules out the match being spurious rather than a real semantic connection.'),
  ('mission-ai-representations-12-o4', 'mission-ai-representations-12', 4, 'Deliver the finding', 'Having confirmed the methodology, read the evidence, and ruled out coincidence, state what tonight''s search actually proved.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-representations-01-o1-c1', 'mission-ai-representations-01-o1', 1, 'multiple_choice', 'Representation learning is best described as...', '{"question":"Representation learning is best described as...","options":[{"id":"a","text":"Memorizing labels for a fixed list of categories"},{"id":"b","text":"Teaching a model to turn raw input into a numerical representation useful for comparison, not just for one narrow task"},{"id":"c","text":"Writing hand-coded rules that convert input into output"},{"id":"d","text":"Compressing data purely to save storage space"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-representations-01-o2-c1', 'mission-ai-representations-01-o2', 1, 'multiple_choice', 'Why is comparing Echo''s message embeddings to the reactor camera embeddings a meaningful question, not a stretch?', '{"question":"Why is comparing Echo''s message embeddings to the reactor camera embeddings a meaningful question, not a stretch?","options":[{"id":"a","text":"Because text and images are secretly the same file format"},{"id":"b","text":"Because if both were built as spaces where distance encodes meaning, proximity across the two spaces can reveal connections no keyword or pixel match ever could"},{"id":"c","text":"Because the two teams happened to use the same programming language"},{"id":"d","text":"It is not meaningful, comparing across modalities never works"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-representations-02-o1-c1', 'mission-ai-representations-02-o1', 1, 'multiple_choice', 'An embedding space is best described as...', '{"question":"An embedding space is best described as...","options":[{"id":"a","text":"A lookup table mapping each input to a fixed category"},{"id":"b","text":"A high-dimensional space where inputs are placed as points, built so that distance between points reflects meaningful similarity"},{"id":"c","text":"A random arrangement of numbers with no structure"},{"id":"d","text":"A compressed image format"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-representations-02-o2-c1', 'mission-ai-representations-02-o2', 1, 'investigation', 'Three messages get embedded. Which arrangement would indicate two of them are semantically similar?', '{"evidence":[{"id":"e1","label":"Embedding plot A","detail":"Message 1 and message 2 land very close together; message 3 lands far from both"},{"id":"e2","label":"Embedding plot B","detail":"All three messages land at exactly the same point"},{"id":"e3","label":"Embedding plot C","detail":"All three messages are spaced randomly with no pattern"}],"question":"Which arrangement indicates two of the messages are semantically similar to each other, and distinct from the third?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-representations-03-o1-c1', 'mission-ai-representations-03-o1', 1, 'drag_and_drop', 'Sort each pair into semantically similar or semantically different, despite what the wording alone suggests.', '{"items":[{"id":"p1","text":"\"The reactor is stable\" and \"Containment holding within normal parameters\""},{"id":"p2","text":"\"The reactor is stable\" and \"The reactor is not stable\""},{"id":"p3","text":"\"I have not stopped\" and \"I am still running\""},{"id":"p4","text":"\"Cats are mammals\" and \"Cats are mammals eating fish\""}],"targets":[{"id":"similar","label":"Semantically similar"},{"id":"different","label":"Semantically different"}]}'::jsonb, '{"correctMapping":{"p1":"similar","p2":"different","p3":"similar","p4":"different"}}'::jsonb),
  ('mission-ai-representations-03-o2-c1', 'mission-ai-representations-03-o2', 1, 'multiple_choice', 'Why does surface-level, word-overlap matching miss genuine semantic similarity?', '{"question":"Why does surface-level, word-overlap matching miss genuine semantic similarity?","options":[{"id":"a","text":"Two sentences can share almost no words and still mean nearly the same thing, or share most words and mean opposite things"},{"id":"b","text":"Word-overlap matching is always more accurate than embeddings"},{"id":"c","text":"Surface matching only fails on very long sentences"},{"id":"d","text":"It does not miss anything, word overlap is a perfect proxy for meaning"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-ai-representations-04-o1-c1', 'mission-ai-representations-04-o1', 1, 'multiple_choice', 'Cosine similarity measures...', '{"question":"Cosine similarity measures...","options":[{"id":"a","text":"The raw Euclidean distance between two vectors, in absolute units"},{"id":"b","text":"The angle between two vectors, independent of their magnitude"},{"id":"c","text":"The number of dimensions two vectors share"},{"id":"d","text":"How many words two sentences have in common"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-representations-04-o2-c1', 'mission-ai-representations-04-o2', 1, 'investigation', 'Three embedding pairs, each with a computed cosine similarity score. Which pair is most similar?', '{"evidence":[{"id":"e1","label":"Pair A","detail":"Cosine similarity of 0.91"},{"id":"e2","label":"Pair B","detail":"Cosine similarity of 0.12"},{"id":"e3","label":"Pair C","detail":"Cosine similarity of -0.65"}],"question":"Which pair is most similar in meaning, according to cosine similarity?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-representations-05-o1-c1', 'mission-ai-representations-05-o1', 1, 'multiple_choice', 'Contrastive learning trains an embedding space by...', '{"question":"Contrastive learning trains an embedding space by...","options":[{"id":"a","text":"Hand-assigning coordinates to every possible input"},{"id":"b","text":"Pulling embeddings of known matching pairs closer together and pushing embeddings of known non-matching pairs farther apart"},{"id":"c","text":"Only ever training on a single example at a time with no comparison involved"},{"id":"d","text":"Randomly initializing embeddings and never updating them"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-representations-05-o2-c1', 'mission-ai-representations-05-o2', 1, 'drag_and_drop', 'Sort each pair into a positive pair (pull together) or a negative pair (push apart).', '{"items":[{"id":"c1","text":"A reactor frame showing normal gauge readings, paired with the caption describing that exact frame"},{"id":"c2","text":"A reactor frame showing normal gauge readings, paired with an unrelated caption about weather"},{"id":"c3","text":"Two different phrasings of the same status update from Echo"},{"id":"c4","text":"An Echo message about containment, paired with an unrelated message about an entirely different topic"}],"targets":[{"id":"positive","label":"Positive pair"},{"id":"negative","label":"Negative pair"}]}'::jsonb, '{"correctMapping":{"c1":"positive","c2":"negative","c3":"positive","c4":"negative"}}'::jsonb),

  ('mission-ai-representations-06-o1-c1', 'mission-ai-representations-06-o1', 1, 'multiple_choice', 'A sentence embedding is best described as...', '{"question":"A sentence embedding is best described as...","options":[{"id":"a","text":"A single point representing an entire sentence, positioned so sentences with related meaning land nearby regardless of exact wording"},{"id":"b","text":"A list of the individual word embeddings with no combination step"},{"id":"c","text":"A count of how many words the sentence contains"},{"id":"d","text":"A random vector reassigned for every sentence"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-representations-06-o2-c1', 'mission-ai-representations-06-o2', 1, 'investigation', 'Two of Echo''s messages, worded completely differently, need to be checked for semantic closeness. Which evidence actually shows that?', '{"evidence":[{"id":"e1","label":"Sentence embedding comparison", "detail":"\"Containment is holding\" and \"Nothing has failed here\" produce sentence embeddings with cosine similarity 0.88"},{"id":"e2","label":"Word count comparison","detail":"The two messages have a different number of words"},{"id":"e3","label":"Timestamp comparison","detail":"The two messages were sent nine days apart"}],"question":"Which evidence actually shows the two differently worded messages are semantically close?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-representations-07-o1-c1', 'mission-ai-representations-07-o1', 1, 'multiple_choice', 'How do an image encoder and a text encoder end up producing comparable embeddings?', '{"question":"How do an image encoder and a text encoder end up producing comparable embeddings?","options":[{"id":"a","text":"They are trained separately with no connection, and comparability is assumed"},{"id":"b","text":"They are trained together, contrastively, on matched image/caption pairs, so a true match lands close together and a mismatch does not"},{"id":"c","text":"Images are first converted into text before embedding"},{"id":"d","text":"They cannot ever be made comparable, images and text are fundamentally incompatible"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-representations-07-o2-c1', 'mission-ai-representations-07-o2', 1, 'drag_and_drop', 'Sort each image/caption pair into matched or mismatched, based on what a well-trained shared embedding space would place close together.', '{"items":[{"id":"m1","text":"A frame showing a green status gauge, paired with the caption \"gauge reading normal\""},{"id":"m2","text":"A frame showing a red warning light, paired with the caption \"gauge reading normal\""},{"id":"m3","text":"A frame showing a coolant pipe, paired with the caption \"coolant line visible in frame\""},{"id":"m4","text":"A frame showing an empty corridor, paired with the caption \"reactor core temperature spike\""}],"targets":[{"id":"matched","label":"Matched"},{"id":"mismatched","label":"Mismatched"}]}'::jsonb, '{"correctMapping":{"m1":"matched","m2":"mismatched","m3":"matched","m4":"mismatched"}}'::jsonb),

  ('mission-ai-representations-08-o1-c1', 'mission-ai-representations-08-o1', 1, 'multiple_choice', 'Retrieval by embedding differs from keyword search because...', '{"question":"Retrieval by embedding differs from keyword search because...","options":[{"id":"a","text":"It finds whatever shares the most exact words with the query"},{"id":"b","text":"It embeds the query and finds whichever stored items sit closest to it in the embedding space, even if they share no words with the query"},{"id":"c","text":"It only works on numerical data, never on text"},{"id":"d","text":"It is identical to keyword search, just renamed"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-representations-08-o2-c1', 'mission-ai-representations-08-o2', 1, 'interactive_diagram', 'Order the steps of embedding-based retrieval.', '{"diagramId":"embedding-retrieval-pipeline","hotspots":[{"id":"query","label":"Receive the query","explanation":"Retrieval starts with whatever the query is -- a message, a phrase, an image."},{"id":"embed-query","label":"Embed the query","explanation":"The query is passed through the same encoder used on the corpus, producing a point in the shared space."},{"id":"compare","label":"Compare against stored embeddings","explanation":"The query embedding is compared, by similarity, against every embedding already stored from the corpus."},{"id":"rank","label":"Rank by similarity","explanation":"Candidates are ordered from most to least similar to the query."},{"id":"return","label":"Return the closest matches","explanation":"The top-ranked, closest items are returned as the retrieval result."}],"task":"Order the steps of embedding-based retrieval from first to last."}'::jsonb, '{"correctOrderIds":["query","embed-query","compare","rank","return"]}'::jsonb),

  ('mission-ai-representations-09-o1-c1', 'mission-ai-representations-09-o1', 1, 'multiple_choice', 'The nearest-neighbor operation is best described as...', '{"question":"The nearest-neighbor operation is best described as...","options":[{"id":"a","text":"Selecting a random subset of candidates"},{"id":"b","text":"Ranking every candidate embedding by its similarity to a query embedding and keeping the closest ones"},{"id":"c","text":"Sorting candidates alphabetically by their original text"},{"id":"d","text":"Selecting candidates with the largest embedding magnitude, regardless of direction"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-representations-09-o2-c1', 'mission-ai-representations-09-o2', 1, 'investigation', 'A query is compared against four candidate embeddings by cosine similarity. Which is the true nearest neighbor?', '{"evidence":[{"id":"e1","label":"Candidate A","detail":"Cosine similarity to query: 0.34"},{"id":"e2","label":"Candidate B","detail":"Cosine similarity to query: 0.77"},{"id":"e3","label":"Candidate C","detail":"Cosine similarity to query: 0.95"},{"id":"e4","label":"Candidate D","detail":"Cosine similarity to query: 0.60"}],"question":"Which candidate is the true nearest neighbor to the query?"}'::jsonb, '{"requiredEvidenceIds":["e3"]}'::jsonb),

  ('mission-ai-representations-10-o1-c1', 'mission-ai-representations-10-o1', 1, 'multiple_choice', 'Why does brute-force nearest neighbor search not survive production scale?', '{"question":"Why does brute-force nearest neighbor search not survive production scale?","options":[{"id":"a","text":"It requires comparing the query against every single stored embedding, so cost grows directly with corpus size, which becomes impractical at millions of items"},{"id":"b","text":"Brute-force search is always less accurate than any index"},{"id":"c","text":"It only works for text embeddings, never for images"},{"id":"d","text":"It has nothing to do with scale, only with accuracy"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-representations-10-o2-c1', 'mission-ai-representations-10-o2', 1, 'drag_and_drop', 'Match each vector index property to whether it favors exact results or favors speed.', '{"items":[{"id":"v1","text":"Comparing the query against every stored embedding with no shortcuts"},{"id":"v2","text":"Clustering embeddings ahead of time and only searching the nearest clusters"},{"id":"v3","text":"Guaranteeing the true nearest neighbors are always found"},{"id":"v4","text":"Accepting an approximate nearest neighbor in exchange for a much faster search"}],"targets":[{"id":"exact","label":"Favors exact results"},{"id":"speed","label":"Favors speed (approximate)"}]}'::jsonb, '{"correctMapping":{"v1":"exact","v2":"speed","v3":"exact","v4":"speed"}}'::jsonb),

  ('mission-ai-representations-11-o1-c1', 'mission-ai-representations-11-o1', 1, 'interactive_diagram', 'Order the stages of a full semantic search pipeline.', '{"diagramId":"semantic-search-pipeline","hotspots":[{"id":"corpus","label":"Collect the corpus","explanation":"Gather every item that should be searchable -- here, Echo''s full message history."},{"id":"embed-corpus","label":"Embed the corpus","explanation":"Run every item through the encoder to produce one embedding per item."},{"id":"build-index","label":"Build the vector index","explanation":"Organize the corpus embeddings into a structure that supports fast nearest-neighbor lookup."},{"id":"embed-query","label":"Embed the query","explanation":"Run the search query through the same encoder used on the corpus."},{"id":"search-index","label":"Search the index for nearest neighbors","explanation":"Use the index to find the corpus embeddings closest to the query embedding."},{"id":"return-results","label":"Return ranked results","explanation":"Present the closest matches, ranked by similarity, as the search result."}],"task":"Order the stages of a full semantic search pipeline from first to last."}'::jsonb, '{"correctOrderIds":["corpus","embed-corpus","build-index","embed-query","search-index","return-results"]}'::jsonb),

  ('mission-ai-representations-12-o1-c1', 'mission-ai-representations-12-o1', 1, 'investigation', 'Before trusting tonight''s result, is the embedding methodology behind it actually sound?', '{"evidence":[{"id":"e1","label":"Methodology note","detail":"Every message in Echo''s history was embedded with the same sentence encoder, in the same embedding space, with no messages skipped or treated differently"},{"id":"e2","label":"Stray log","detail":"Facilities log shows normal cooling system activity overnight"},{"id":"e3","label":"Unrelated ticket","detail":"An open ticket about dashboard color scheme preferences"}],"question":"Which evidence confirms the embedding methodology behind tonight''s search is sound?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-representations-12-o2-c1', 'mission-ai-representations-12-o2', 1, 'investigation', 'What does the cosine-similarity evidence actually show about Echo''s most recent unusual message?', '{"evidence":[{"id":"e1","label":"Similarity ranking","detail":"Against every message in Echo''s full history, the highest cosine similarity by a wide margin belongs to a message from the first few hours after activation -- far higher than any similarity score to messages sent in the months between"},{"id":"e2","label":"Recent message scan","detail":"Messages sent in the days immediately before the unusual one score only moderate similarity to it"},{"id":"e3","label":"Volume count","detail":"Echo has sent several thousand messages in total since activation"}],"question":"Which evidence shows what the most recent unusual message is actually closest to in meaning?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-representations-12-o3-c1', 'mission-ai-representations-12-o3', 1, 'investigation', 'Could the high similarity to the early-activation message be a coincidence rather than a real connection?', '{"evidence":[{"id":"e1","label":"Margin check","detail":"The top match''s similarity score is far higher than every other candidate, not a narrow, ambiguous lead over the next-closest message"},{"id":"e2","label":"Encoder consistency check","detail":"The same encoder and methodology that found this match was validated earlier by correctly matching pairs of messages already known to be related"},{"id":"e3","label":"Unrelated coincidence example","detail":"A different, deliberately unrelated pair of messages was checked and scored a low similarity, as expected"}],"question":"Which evidence set most directly rules out this being a spurious, coincidental match?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),
  ('mission-ai-representations-12-o4-c1', 'mission-ai-representations-12-o4', 1, 'boss_encounter', 'Having confirmed the methodology, read the similarity evidence, and ruled out coincidence, state what tonight''s semantic search actually proved.', '{"stages":[{"objectiveRef":"mission-ai-representations-12-o1","label":"Confirm the methodology"},{"objectiveRef":"mission-ai-representations-12-o2","label":"Read the evidence"},{"objectiveRef":"mission-ai-representations-12-o3","label":"Rule out coincidence"}],"task":"State the finding: Echo''s most recent unusual message sits closer, in meaning, to something from the first hours after activation than to anything said in the months between -- a real, provable connection across the entire timeline, even though what it means is still unknown."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-representations-12-o1","mission-ai-representations-12-o2","mission-ai-representations-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-representations-01-o1-c1', 'orientation', 'Think about what the representation is supposed to be useful for, beyond just one prediction task.', 10, 1),
  ('mission-ai-representations-01-o1-c1', 'solution', 'Representation learning teaches a model to turn raw input into a representation useful for comparison broadly, not one hand-coded rule or one narrow task.', 20, 2),
  ('mission-ai-representations-01-o2-c1', 'orientation', 'The question only makes sense if distance means the same kind of thing in both spaces.', 10, 1),
  ('mission-ai-representations-01-o2-c1', 'solution', 'If both spaces were built so distance encodes meaning, proximity across them can surface connections no single-modality search could ever find.', 20, 2),

  ('mission-ai-representations-02-o1-c1', 'orientation', 'An embedding space is not a category system -- it is geometry.', 10, 1),
  ('mission-ai-representations-02-o1-c1', 'solution', 'It is a high-dimensional space where inputs become points, arranged so that distance between points reflects meaningful similarity.', 20, 2),
  ('mission-ai-representations-02-o2-c1', 'orientation', 'Look for the plot where two points are close and the third stands apart.', 10, 1),
  ('mission-ai-representations-02-o2-c1', 'solution', 'e1: message 1 and message 2 clustering close together, apart from message 3, is exactly what semantic similarity should look like in the space.', 20, 2),

  ('mission-ai-representations-03-o1-c1', 'orientation', 'Watch for a single negation flipping meaning despite heavy word overlap, and paraphrases that share almost no words.', 10, 1),
  ('mission-ai-representations-03-o1-c1', 'solution', 'Similar: the containment paraphrase, and "I have not stopped" versus "I am still running." Different: the negated reactor-stability pair, and the mammals pair with an added false claim.', 20, 2),
  ('mission-ai-representations-03-o2-c1', 'orientation', 'Think about a negation that changes everything while barely changing the words.', 10, 1),
  ('mission-ai-representations-03-o2-c1', 'solution', 'Two sentences can share almost no words and mean nearly the same thing, or share most words and mean opposite things -- word overlap and meaning are not the same axis.', 20, 2),

  ('mission-ai-representations-04-o1-c1', 'orientation', 'Cosine similarity ignores how long a vector is and looks only at where it points.', 10, 1),
  ('mission-ai-representations-04-o1-c1', 'solution', 'It measures the angle between two vectors, independent of magnitude -- direction, not raw distance.', 20, 2),
  ('mission-ai-representations-04-o2-c1', 'orientation', 'Higher cosine similarity means more similar. Negative values mean pointing in opposite directions.', 10, 1),
  ('mission-ai-representations-04-o2-c1', 'solution', 'Pair A, at 0.91, is by far the most similar -- close to 1 means the vectors point in nearly the same direction.', 20, 2),

  ('mission-ai-representations-05-o1-c1', 'orientation', 'The training signal is pairs, not individual hand-assigned coordinates.', 10, 1),
  ('mission-ai-representations-05-o1-c1', 'solution', 'Contrastive learning pulls known matching pairs together and pushes known non-matching pairs apart, across many pairs, and the space''s geometry emerges from that.', 20, 2),
  ('mission-ai-representations-05-o2-c1', 'orientation', 'A positive pair is a true match. A negative pair has nothing to do with each other.', 10, 1),
  ('mission-ai-representations-05-o2-c1', 'solution', 'Positive: the frame with its true caption, and the two phrasings of the same status. Negative: the frame with an unrelated caption, and the containment message with an unrelated topic.', 20, 2),

  ('mission-ai-representations-06-o1-c1', 'orientation', 'A sentence embedding is one point for the whole sentence, not a list of separate word points.', 10, 1),
  ('mission-ai-representations-06-o1-c1', 'solution', 'It is a single point representing the whole sentence, positioned so related meanings land nearby regardless of exact wording.', 20, 2),
  ('mission-ai-representations-06-o2-c1', 'orientation', 'Word count and timestamps say nothing about meaning.', 10, 1),
  ('mission-ai-representations-06-o2-c1', 'solution', 'e1: a 0.88 cosine similarity between two differently worded messages is direct evidence they are semantically close.', 20, 2),

  ('mission-ai-representations-07-o1-c1', 'orientation', 'The two encoders need a shared training signal to end up in the same space at all.', 10, 1),
  ('mission-ai-representations-07-o1-c1', 'solution', 'They are trained together, contrastively, on matched image/caption pairs, so true matches land close and mismatches do not.', 20, 2),
  ('mission-ai-representations-07-o2-c1', 'orientation', 'Ask whether the caption actually describes what is visible in that specific frame.', 10, 1),
  ('mission-ai-representations-07-o2-c1', 'solution', 'Matched: the green-gauge frame with its accurate caption, and the coolant-pipe frame with its accurate caption. Mismatched: the red-warning frame captioned "normal," and the empty corridor captioned as a temperature spike.', 20, 2),

  ('mission-ai-representations-08-o1-c1', 'orientation', 'Retrieval by embedding never checks for shared words at all.', 10, 1),
  ('mission-ai-representations-08-o1-c1', 'solution', 'It embeds the query and finds whichever stored items are closest in the embedding space, even with zero words in common.', 20, 2),
  ('mission-ai-representations-08-o2-c1', 'orientation', 'The query has to become an embedding before anything can be compared against it.', 10, 1),
  ('mission-ai-representations-08-o2-c1', 'solution', 'Receive the query, embed it, compare against stored embeddings, rank by similarity, return the closest matches.', 20, 2),

  ('mission-ai-representations-09-o1-c1', 'orientation', 'This is the ranking step underneath retrieval, not a random sample.', 10, 1),
  ('mission-ai-representations-09-o1-c1', 'solution', 'It ranks every candidate by similarity to the query and keeps the closest ones.', 20, 2),
  ('mission-ai-representations-09-o2-c1', 'orientation', 'Higher cosine similarity is closer.', 10, 1),
  ('mission-ai-representations-09-o2-c1', 'solution', 'Candidate C, at 0.95, is the true nearest neighbor -- the highest similarity score of the four.', 20, 2),

  ('mission-ai-representations-10-o1-c1', 'orientation', 'Think about what happens to search cost as the corpus grows into the millions.', 10, 1),
  ('mission-ai-representations-10-o1-c1', 'solution', 'Brute force compares the query against every stored embedding, so cost scales directly with corpus size -- impractical at real production scale.', 20, 2),
  ('mission-ai-representations-10-o2-c1', 'orientation', 'Checking everything guarantees correctness. Skipping most of the corpus trades some correctness for speed.', 10, 1),
  ('mission-ai-representations-10-o2-c1', 'solution', 'Exact: comparing against everything, and guaranteeing the true nearest neighbors. Speed: clustering ahead of time to search only nearby clusters, and accepting approximate results for a faster search.', 20, 2),

  ('mission-ai-representations-11-o1-c1', 'orientation', 'The index cannot be built before the corpus is embedded, and nothing can be searched before the index exists.', 10, 1),
  ('mission-ai-representations-11-o1-c1', 'concept', 'The query has to be embedded with the same encoder used on the corpus, or the two would not live in a comparable space.', 20, 2),
  ('mission-ai-representations-11-o1-c1', 'solution', 'Collect the corpus, embed the corpus, build the vector index, embed the query, search the index for nearest neighbors, return ranked results.', 30, 3),

  ('mission-ai-representations-12-o1-c1', 'orientation', 'A sound methodology treats every item in the corpus the same way, with no shortcuts or exceptions.', 10, 1),
  ('mission-ai-representations-12-o1-c1', 'solution', 'e1: the same encoder and same space were used across the entire message history with nothing skipped -- the methodology is sound.', 20, 2),
  ('mission-ai-representations-12-o2-c1', 'orientation', 'Compare the top similarity score against scores from messages sent closer in time to the unusual one.', 10, 1),
  ('mission-ai-representations-12-o2-c1', 'solution', 'e1: the highest similarity by a wide margin belongs to a message from the first hours after activation, well above any score from the intervening months.', 20, 2),
  ('mission-ai-representations-12-o3-c1', 'orientation', 'A real connection should show a clear margin over the next-best candidate, and the method finding it should already be validated on known cases.', 10, 1),
  ('mission-ai-representations-12-o3-c1', 'solution', 'e1 and e2 together rule out coincidence: the margin over every other candidate is wide, not narrow and ambiguous, and the same encoder was already shown to correctly match known-related pairs.', 20, 2),
  ('mission-ai-representations-12-o4-c1', 'orientation', 'State what the search proved, not what it did not -- the connection is confirmed, even if its meaning is not.', 15, 1),
  ('mission-ai-representations-12-o4-c1', 'solution', 'Echo''s most recent unusual message is provably closest, in meaning, to a message from the first hours after activation -- a real connection across the entire timeline that nobody had found before, even though what it actually means is still unknown.', 25, 2);
